// Decode generated bytes with the firmware's real readers, including its calibration acceptance checks.
#include <assert.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "vboard.h"
#include "vhost.h"
#include "vtrace.h"
#include "codeplug/codeplug.h"
#include "settings/settings.h"
#include "storage/storage.h"
#include "md380.h"

static const band_t bands[] = { { 400000000u, 480000000u, true } };
const board_t board = { .name = "Virtual", .flash = &vboard_flash, .bands = bands, .band_count = 1, .power_count = 2 };
void storage_lock(void) {}
void storage_unlock(void) {}
void storage_quick_lock(void) {}
void storage_quick_unlock(void) {}
void vtrace(const char *fmt, ...) { (void)fmt; }
uint64_t vtrace_hash(const void *data, size_t n) { (void)data; (void)n; return 0; }
void vhost_option_register(const vhost_option_t *opt) { (void)opt; }
void vhost_finish(const char *why, int code) { fprintf(stderr, "%s\n", why); exit(code); }

static uint8_t security[768];
bool stm32_spi_flash_read_security(uint8_t reg, uint32_t offset, void *buf, uint32_t len)
{
	if (reg < 1 || reg > 3 || offset > 256 || len > 256 - offset)
		return false;
	memcpy(buf, security + (reg - 1) * 256 + offset, len);
	return true;
}

int main(int argc, char **argv)
{
	assert(argc == 5);
	FILE *f = fopen(argv[1], "rb");
	assert(f);
	uint8_t block[4096];
	vboard_flash_boot();
	for (uint32_t at = 0; at < vboard_flash.size; at += sizeof block) {
		assert(fread(block, 1, sizeof block, f) == sizeof block);
		assert(vflash_load(at, block, sizeof block));
	}
	assert(fgetc(f) == EOF);
	assert(fclose(f) == 0);
	f = fopen(argv[2], "rb");
	assert(f && fread(security, 1, sizeof security, f) == sizeof security);
	assert(fgetc(f) == EOF);
	assert(fclose(f) == 0);
	assert(md380_cal_load());
	// The retained fixture has no last band endpoint; the reader uses its default grid (hardware spec 11.2).
	assert(strcmp(md380_cal_source(), "factory/grid") == 0 && strcmp(md380_cal_why(), "ok") == 0);
	md380_cal_point_t point;
	assert(md380_cal_at(433500000, &point) && point.valid);
	assert(point.power_dac[0] == 382 && point.power_dac[1] == 1275);
	assert(point.rx_tune_dac == 2040 && point.ref_tune == 64);
	assert(point.dmr_i == 64 && point.dmr_q == 64 && point.fm_i == 64 && point.fm_q == 64);
	assert(storage_init());
	settings_init();
	codeplug_init();
	if (strcmp(argv[3], "blank") != 0) {
		unsigned index = (unsigned)strtoul(argv[4], NULL, 10);
		bool pair = strcmp(argv[3], "dmr-pair") == 0;
		assert(codeplug_dmr_id() == 3100000 + index);
		char name[CODEPLUG_NAME_LEN + 1];
		codeplug_radio_name(name);
		assert(strcmp(name, "N0SIM") == 0);
		channel_t ch;
		assert(codeplug_channel(1, &ch));
		assert(strcmp(ch.name, pair ? "Simplex" : "Group") == 0);
		assert(ch.rx_hz == 433500000 && ch.tx_hz == ch.rx_hz && ch.mode == RADIO_MODE_DMR);
		assert(ch.color_code == 1 && ch.timeslot == 1 && ch.contact == 1 && ch.dmo);
		contact_t contact;
		assert(codeplug_contact(1, &contact));
		assert(contact.id == (pair ? 3100003 - index : 9));
		assert(contact.type == (pair ? CONTACT_PRIVATE : CONTACT_GROUP) && contact.timeslot == 1);
		zone_t zone;
		assert(codeplug_zone(0, &zone) && zone.count == 1 && zone.channels[0] == 1);
		assert(strcmp(zone.name, pair ? "Pair" : "Group") == 0);
		settings_t settings;
		settings_read(&settings);
		assert(settings.channel == 1 && settings.vfo == 0);
	}
	printf("%s radio %s: firmware storage decode and calibration factory/grid/ok PASSED\n", argv[3], argv[4]);
	return 0;
}
